# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">3. TEMA: DUYGULARIMI TANIYORUM — DUYGU İFADELERİ VE ANLAM (T.D.5.2 / T.O.5.5)</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Temel Duygularımız</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Sevinç, heyecan ve mutluluk</text>\n  <text x="125" y="120" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Üzüntü, özlem ve hüzün</text>\n  <text x="125" y="142" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Şaşkınlık, merak ve endişe (kaygı)</text>\n  <text x="125" y="164" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Korku, öfke ve pişmanlık</text>\n  <text x="125" y="186" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Merhamet, şefkat ve minnet</text>\n  <text x="125" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Her duygu doğaldır ve bizi korur.</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fdf2f8" stroke="#db2777" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Duygu Bildiren Deyimler</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11.5" fill="#831843">• Etekleri zil çalmak (Çok sevinmek)</text>\n  <text x="350" y="120" text-anchor="middle" font-size="11.5" fill="#831843">• Ağzı kulaklarına varmak (Mutluluk)</text>\n  <text x="350" y="142" text-anchor="middle" font-size="11.5" fill="#831843">• İçi cız etmek (Derin üzüntü duymak)</text>\n  <text x="350" y="164" text-anchor="middle" font-size="11.5" fill="#831843">• Gözleri fal taşı gibi açılmak (Şaşma)</text>\n  <text x="350" y="186" text-anchor="middle" font-size="11.5" fill="#831843">• Küplere binmek (Çok öfkelenmek)</text>\n  <text x="350" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">• Yüreği ağzına gelmek (Çok korkmak)</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Yüzey Anlam ve Derin Anlam</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11.5" fill="#14532d">• Yüzey Anlam: Metinde doğrudan</text>\n  <text x="575" y="118" text-anchor="middle" font-size="11.5" fill="#14532d">ve açıkça söylenen bilgilerdir.</text>\n  <text x="575" y="144" text-anchor="middle" font-size="11.5" fill="#14532d">• Derin Anlam: İpuçları, beden dili</text>\n  <text x="575" y="164" text-anchor="middle" font-size="11.5" fill="#14532d">ve ön bilgilerle çıkarım yapılarak</text>\n  <text x="575" y="184" text-anchor="middle" font-size="11.5" fill="#14532d">ulaşılan örtük mesajdır.</text>\n  <text x="575" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Empati duyguları anlamayı sağlar.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÖZNEL VE NESNEL YARGILAR İLE DÜŞÜNCEYİ GELİŞTİRME YOLLARI</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Nesnel Yargı (Kanıtlanabilir Gerçek)</text>\n  <text x="180" y="98" text-anchor="middle" font-size="11.5" fill="#78350f">• Kişisel duygu ve beğeni içermez; herkes</text>\n  <text x="180" y="118" text-anchor="middle" font-size="11.5" fill="#78350f">için aynıdır, doğruluğu/yanlışlığı kanıtlanır.</text>\n  <text x="180" y="146" text-anchor="middle" font-size="11.5" fill="#78350f">• Örnek 1: «Metin dört paragraftan oluşmaktadır.»</text>\n  <text x="180" y="170" text-anchor="middle" font-size="11.5" fill="#78350f">• Örnek 2: «Korku anında kalp atışı hızlanır.»</text>\n  <text x="180" y="194" text-anchor="middle" font-size="11.5" fill="#78350f">• Düşünceyi Geliştirme: Tanımlama (...nedir?)</text>\n  <text x="180" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">ve Örneklendirme (somut örnek verme)</text>\n\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#ecfeff" stroke="#0891b2" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Öznel Yargı (Kişisel Görüş ve Duygu)</text>\n  <text x="520" y="98" text-anchor="middle" font-size="11.5" fill="#155e75">• Söyleyenin kendi duygusunu, beğenisini ve</text>\n  <text x="520" y="118" text-anchor="middle" font-size="11.5" fill="#155e75">yorumunu içerir; kişiden kişiye değişir, kanıtlanamaz.</text>\n  <text x="520" y="146" text-anchor="middle" font-size="11.5" fill="#155e75">• Örnek 1: «Sonbahar insanın içine tatlı bir huzur verir.»</text>\n  <text x="520" y="170" text-anchor="middle" font-size="11.5" fill="#155e75">• Örnek 2: «Yazarın en etkileyici eseri bu öyküdür.»</text>\n  <text x="520" y="194" text-anchor="middle" font-size="11.5" fill="#155e75">• Düşünceyi Geliştirme: Karşılaştırma (en, daha,</text>\n  <text x="520" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">ise, göre) ve Benzetme (gibi, tıpkı, misali)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SÖZ SANATLARI: BENZETME (TEŞBİH) VE KİŞİLEŞTİRME (TEŞHİS)</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#f5f3ff" stroke="#7c3aed" stroke-width="1.5"/>\n  <text x="180" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#5b21b6">Benzetme (Teşbih)</text>\n  <text x="180" y="100" text-anchor="middle" font-size="11.5" fill="#4c1d95">• Aralarında ilgi bulunan iki varlıktan zayıf</text>\n  <text x="180" y="120" text-anchor="middle" font-size="11.5" fill="#4c1d95">olanın güçlü olana benzetilmesidir.</text>\n  <text x="180" y="146" text-anchor="middle" font-size="11.5" fill="#4c1d95">• Unsurları: Benzeyen, Kendisine Benzetilen,</text>\n  <text x="180" y="166" text-anchor="middle" font-size="11.5" fill="#4c1d95">Benzetme Yönü ve Edatı (gibi, kadar, sanki).</text>\n  <text x="180" y="194" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#5b21b6">«Öfke, saman alevi gibi hızla parlayıp söner.»</text>\n  <text x="180" y="218" text-anchor="middle" font-size="11" fill="#4c1d95">(Benzeyen: Öfke · Benzetilen: Saman alevi)</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="520" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Kişileştirme (Teşhis)</text>\n  <text x="520" y="100" text-anchor="middle" font-size="11.5" fill="#14532d">• İnsan dışındaki varlıklara (doğa, hayvan, cansız</text>\n  <text x="520" y="120" text-anchor="middle" font-size="11.5" fill="#14532d">nesne, kavram) insana özgü duygu, düşünce</text>\n  <text x="520" y="140" text-anchor="middle" font-size="11.5" fill="#14532d">ve davranış özellikleri verilmesidir.</text>\n  <text x="520" y="170" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">«Yalnız kalan yaşlı çınar ağacı hüzünle ağlıyordu.»</text>\n  <text x="520" y="194" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">«Güneş bulutların arasından bize gülümsedi.»</text>\n  <text x="520" y="218" text-anchor="middle" font-size="11" fill="#14532d">(Ağlamak, hüzünlenmek ve gülümsemek insana özgüdür)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
